/**
 * Persian text tooling.
 *
 * This is the part of B mark that no other editor does properly, and it exists
 * because Persian writers currently fix all of this by hand.
 *
 * Text pasted from the web, produced by an OCR, typed on an Arabic keyboard
 * layout, or generated by a model is routinely wrong in the same handful of
 * ways: Arabic ي and ك instead of Persian ی and ک, missing zero-width
 * non-joiners, a space before a comma, mixed digit systems. None of these are
 * spelling mistakes a spell-checker would catch — they are encoding and
 * typography problems — and every one of them makes the text render or search
 * incorrectly.
 *
 * Design rules for everything in here:
 *
 *   1. **Never touch code, URLs or file paths.** `کتاب ها` becomes `کتاب‌ها`,
 *      but `some_var ها` inside a code span is left exactly as written. Every
 *      transform runs on prose only, with fenced blocks, inline code, links
 *      and paths masked out first.
 *   2. **Never change meaning.** These are reversible typographic
 *      normalisations, not rewrites. Nothing here paraphrases.
 *   3. **Every rule is individually switchable**, because house styles differ —
 *      some publications want Persian digits, some insist on ASCII.
 */

export interface PersianFixOptions {
  /** ي ك ة → ی ک ه, and Arabic alef variants. */
  normaliseLetters: boolean;
  /** Insert ZWNJ in می‌/نمی‌ prefixes and ‌ها/‌تر/‌ترین/‌های suffixes. */
  fixZwnj: boolean;
  /** Remove the space before ، . ؟ ! : ; and ensure one after. */
  fixPunctuationSpacing: boolean;
  /** Arabic comma/semicolon/question mark → Persian equivalents. */
  normalisePunctuation: boolean;
  /** Convert digits. 'fa' → ۰-۹, 'en' → 0-9, 'keep' → leave alone. */
  digits: 'fa' | 'en' | 'keep';
  /** Collapse runs of spaces and strip trailing whitespace. */
  tidyWhitespace: boolean;
  /** Straight quotes around Persian text → « ». */
  persianQuotes: boolean;
}

export const DEFAULT_FIX_OPTIONS: PersianFixOptions = {
  normaliseLetters: true,
  fixZwnj: true,
  fixPunctuationSpacing: true,
  normalisePunctuation: true,
  // Left alone by default: digit style is a house-style decision, and silently
  // rewriting numbers in someone's document is presumptuous.
  digits: 'keep',
  tidyWhitespace: true,
  persianQuotes: false,
};

export interface FixReport {
  text: string;
  /** How many replacements each rule made, for an honest summary. */
  counts: Record<string, number>;
  get total(): number;
}

// ---------------------------------------------------------------- masking --

/**
 * Spans that must survive untouched. Order matters: fenced blocks first, so a
 * `#` inside one is not mistaken for anything else.
 */
const PROTECTED: ReadonlyArray<RegExp> = [
  /```[\s\S]*?```/g, // fenced code
  /~~~[\s\S]*?~~~/g,
  /`[^`\n]*`/g, // inline code
  /^\s{4,}\S.*$/gm, // indented code
  /<[^>\n]{1,300}>/g, // html tags
  /\b[a-z][a-z0-9+.-]{1,15}:\/\/\S+/gi, // scheme://…
  /\b[A-Za-z]:\\[^\s)]+/g, // C:\path
  /\]\([^)\s]*\)/g, // link targets
  // `\w` is ASCII-only in JavaScript, so a local part containing Persian
  // letters would not have matched and the address would have been rewritten.
  /[\p{L}\p{N}._+-]+@[\p{L}\p{N}-]+\.[\p{L}\p{N}.-]+/gu, // e-mail
  /\$\$[\s\S]*?\$\$/g, // block math
  /(?<!\\)\$[^$\n]+\$/g, // inline math
];

const SENTINEL = '\u0000';

interface Masked {
  text: string;
  restore: (input: string) => string;
}

function mask(input: string): Masked {
  const kept: string[] = [];
  let text = input;

  for (const re of PROTECTED) {
    text = text.replace(re, (match) => {
      kept.push(match);
      return `${SENTINEL}${kept.length - 1}${SENTINEL}`;
    });
  }

  return {
    text,
    restore: (out) =>
      out.replace(new RegExp(`${SENTINEL}(\\d+)${SENTINEL}`, 'g'), (_, i: string) => kept[Number(i)] ?? ''),
  };
}

// ------------------------------------------------------------------ rules --

const ZWNJ = '\u200c';

const LETTER_MAP: ReadonlyArray<[RegExp, string]> = [
  [/\u064A/g, '\u06CC'], // ي → ی  ARABIC YEH
  [/\u0649/g, '\u06CC'], // ى → ی  ALEF MAKSURA
  [/\u0643/g, '\u06A9'], // ك → ک  ARABIC KAF
  [/\u06AA/g, '\u06A9'], // ڪ → ک  SWASH KAF
  [/\u0629/g, '\u0647'], // ة → ه  TEH MARBUTA
  [/\u0623|\u0625/g, '\u0627'], // أ إ → ا
  [/\u06C0/g, '\u0647\u200c\u06CC'], // ۀ → ه‌ی
];

/**
 * Prefixes that take a ZWNJ. Only the unambiguous ones: `می` and `نمی` before
 * a verb. `می` is also the noun "wine", so the rule requires a following word
 * of at least three letters, which avoids "می ناب".
 */
const ZWNJ_PREFIX = /(^|[\s،؛:.!؟(«"])(ن?می) ([\u0600-\u06FF]{3,})/gu;

/**
 * Suffixes that take a ZWNJ. `ها` and its inflections, comparatives, and the
 * indefinite `ای`. Deliberately conservative: only after a word ending in a
 * Persian letter, and only when the suffix stands as its own token.
 */
const ZWNJ_SUFFIX =
  /([\u0600-\u06FF]{2,}) (ها|های|هایی|هایم|هایت|هایش|تر|تری|ترین|ام|ات|اش|اید|اند)(?=[\s،؛:.!؟)»"]|$)/gu;

/** Arabic punctuation that has a Persian counterpart. */
const PUNCT_MAP: ReadonlyArray<[RegExp, string]> = [
  [/\u066B/g, '\u066B'], // decimal separator: unchanged, listed for clarity
  [/,(?=\s|$)/g, '\u060C'], // ASCII comma in Persian prose → ،
  [/;(?=\s|$)/g, '\u061B'], // ; → ؛
  [/\?(?=\s|$)/g, '\u061F'], // ? → ؟
];

const PERSIAN_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
const ARABIC_DIGITS = '٠١٢٣٤٥٦٧٨٩';

function countReplacements(before: string, after: string): number {
  if (before === after) return 0;
  let n = 0;
  const len = Math.min(before.length, after.length);
  for (let i = 0; i < len; i++) if (before[i] !== after[i]) n++;
  return Math.max(1, n + Math.abs(before.length - after.length));
}

/** Is this text Persian/Arabic enough that Persian punctuation rules apply? */
export function isPersianText(text: string): boolean {
  const persian = text.match(/[\u0600-\u06FF]/g)?.length ?? 0;
  const latin = text.match(/[A-Za-z]/g)?.length ?? 0;
  return persian > 0 && persian >= latin;
}

/**
 * Apply the selected fixes and report what changed.
 */
export function fixPersianText(
  input: string,
  options: Partial<PersianFixOptions> = {},
): FixReport {
  const opts = { ...DEFAULT_FIX_OPTIONS, ...options };
  const counts: Record<string, number> = {};

  const masked = mask(input);
  let text = masked.text;

  const step = (name: string, fn: (s: string) => string) => {
    const before = text;
    text = fn(text);
    const n = countReplacements(before, text);
    if (n > 0) counts[name] = (counts[name] ?? 0) + n;
  };

  if (opts.normaliseLetters) {
    step('letters', (s) => {
      for (const [re, to] of LETTER_MAP) s = s.replace(re, to);
      return s;
    });
  }

  if (opts.digits !== 'keep') {
    step('digits', (s) =>
      opts.digits === 'fa'
        ? s.replace(/[0-9]/g, (d) => PERSIAN_DIGITS[Number(d)]!).replace(
            /[٠-٩]/g,
            (d) => PERSIAN_DIGITS[ARABIC_DIGITS.indexOf(d)]!,
          )
        : s
            .replace(/[۰-۹]/g, (d) => String(PERSIAN_DIGITS.indexOf(d)))
            .replace(/[٠-٩]/g, (d) => String(ARABIC_DIGITS.indexOf(d))),
    );
  }

  if (opts.normalisePunctuation && isPersianText(input)) {
    step('punctuation', (s) => {
      for (const [re, to] of PUNCT_MAP) s = s.replace(re, to);
      return s;
    });
  }

  if (opts.fixZwnj) {
    step('zwnj', (s) => {
      // Run the prefix rule twice: "نمی می خواهم" needs two passes.
      s = s.replace(ZWNJ_PREFIX, `$1$2${ZWNJ}$3`);
      s = s.replace(ZWNJ_PREFIX, `$1$2${ZWNJ}$3`);
      s = s.replace(ZWNJ_SUFFIX, `$1${ZWNJ}$2`);
      // Collapse a doubled ZWNJ and drop one adjacent to a space.
      s = s.replace(new RegExp(`${ZWNJ}{2,}`, 'g'), ZWNJ);
      s = s.replace(new RegExp(`\\s${ZWNJ}|${ZWNJ}\\s`, 'g'), ' ');
      return s;
    });
  }

  if (opts.fixPunctuationSpacing) {
    step('spacing', (s) =>
      s
        // No space before Persian or ASCII closing punctuation.
        .replace(/\s+([،؛؟!:.](?=\s|$))/g, '$1')
        // Exactly one space after it, when a word follows.
        .replace(/([،؛؟!:])(?=[^\s\d])/g, '$1 ')
        // No space just inside brackets and Persian quotes.
        .replace(/([(«\[])\s+/g, '$1')
        .replace(/\s+([)»\]])/g, '$1'),
    );
  }

  if (opts.persianQuotes) {
    step('quotes', (s) => s.replace(/"([^"\n]{1,200})"/g, '«$1»'));
  }

  if (opts.tidyWhitespace) {
    step('whitespace', (s) =>
      s
        .replace(/[ \t]{2,}/g, ' ')
        .replace(/[ \t]+$/gm, '')
        // Three or more blank lines collapse to one blank line.
        .replace(/\n{4,}/g, '\n\n\n'),
    );
  }

  const result = masked.restore(text);

  return {
    text: result,
    counts,
    get total() {
      return Object.values(counts).reduce((a, b) => a + b, 0);
    },
  };
}

/** Insert a ZWNJ at the caret — bound to Ctrl+Shift+Space in the editor. */
export const ZWNJ_CHAR = ZWNJ;
